import{_ as d,o as e,c as a,ag as o}from"./chunks/framework.DMXcdKmJ.js";const m=JSON.parse('{"title":"安装参数","description":"查询中心安装向导的字段、默认值、限制和两个入口的地址形式。","frontmatter":{"title":"安装参数","description":"查询中心安装向导的字段、默认值、限制和两个入口的地址形式。","status":"reviewed","kind":"reference"},"headers":[],"relativePath":"zh/reference/install-options.md","filePath":"zh/参考资料/安装参数.md"}'),r={name:"zh/reference/install-options.md"};function c(h,t,l,i,n,s){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="安装参数" tabindex="-1">安装参数 <a class="header-anchor" href="#安装参数" aria-label="Permalink to &quot;安装参数&quot;">​</a></h1><p>本页供填写中心安装向导时查询。完整操作顺序见<a href="/induframe-docs/zh/installation/install.html">安装中心</a>，环境条件见<a href="/induframe-docs/zh/installation/prepare.html">安装前准备</a>。</p><p>当前为 v1.0，优先使用已测试的 Ubuntu 24；其他系统尚未测试。第一次安装可先跟随向导操作，需要查询限制时再回到本页。系统范围见<a href="/induframe-docs/zh/reference/system-requirements.html">系统与安装要求</a>。</p><h2 id="启动方式" tabindex="-1">启动方式 <a class="header-anchor" href="#启动方式" aria-label="Permalink to &quot;启动方式&quot;">​</a></h2><p>在完整安装包目录执行 <code>./install.sh</code>，安装和完整更新均不需要参数。查看帮助使用 <code>./install.sh -h</code>，其他参数不接受。已完成安装时会显示 <code>1) 更新</code>、<code>2) 取消</code>；输入 <code>1</code> 才更新，输入 <code>2</code> 或回车取消。更新沿用原安装设置，不重新填写下方初装字段。</p><h2 id="向导字段" tabindex="-1">向导字段 <a class="header-anchor" href="#向导字段" aria-label="Permalink to &quot;向导字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th><th>填写要求</th><th>影响与示例</th></tr></thead><tbody><tr><td>存放位置</td><td><code>/opt</code></td><td>可用的绝对目录，不能是根目录、受限系统路径、文件、符号链接路径或安装包内部</td><td>自动追加 <code>induframe</code>；输入 <code>/srv/platform</code>，程序目录为 <code>/srv/platform/induframe</code></td></tr><tr><td>公共访问地址或域名</td><td>安装器识别的当前主机地址</td><td>用户浏览器能够访问的地址；域名需要正确解析</td><td>示例域名 <code>platform.example.com</code> 仅为说明，不能直接照填</td></tr><tr><td>公共访问端口</td><td><code>443</code></td><td>1–65535 的整数，不与管理端口重复或被其他服务占用</td><td>当前向导固定使用 HTTPS；非默认端口需要写进访问地址</td></tr><tr><td>管理入口端口</td><td><code>18100</code></td><td>1–65535 的整数，与公共端口不同</td><td>管理地址由安装器选择内网 IPv4，使用安装结果打印的完整地址</td></tr><tr><td>平台超级管理员用户名</td><td><code>admin</code></td><td>3–50 个标识字符，以向导校验结果为准</td><td>该账号用于管理入口，和组织内账号分开</td></tr><tr><td>TLS 模式</td><td><code>self-signed</code></td><td><code>self-signed</code> 或 <code>provided</code></td><td>前者生成自签名证书；后者需要证书文件、私钥文件和可选 CA 文件的绝对路径</td></tr><tr><td>平台超级管理员初始密码</td><td>无</td><td>输入两次，8–72 字节，两次必须一致</td><td>使用 ASCII 字符时一个字符为一个字节；中文等字符会占多个字节</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">密码长度</p><p>终端提示使用“字符”描述长度，当前校验实际按字节计数。建议使用 8–72 个 ASCII 字符设置初始密码；不要据提示推算多字节密码一定可接受。</p></div><h2 id="账号与密码" tabindex="-1">账号与密码 <a class="header-anchor" href="#账号与密码" aria-label="Permalink to &quot;账号与密码&quot;">​</a></h2><table tabindex="0"><thead><tr><th>密码用于什么</th><th>当前实际校验</th><th>建议怎样设置</th></tr></thead><tbody><tr><td>安装时的平台超级管理员</td><td>8–72 字节，输入两次一致</td><td>使用 8–72 个英文字母、数字或半角符号</td></tr><tr><td>首次设置时重置组织管理员密码</td><td>1–72 字节，不能全为空白，输入两次一致</td><td>同样建议使用 8–72 个英文字母、数字或半角符号</td></tr></tbody></table><p>中文等字符占用多个字节；不要按屏幕显示的字符个数推算是否符合限制。上表区分实际校验和推荐写法，两类账号的密码分别保管。</p><h2 id="证书选择" tabindex="-1">证书选择 <a class="header-anchor" href="#证书选择" aria-label="Permalink to &quot;证书选择&quot;">​</a></h2><p><code>self-signed</code> 用于由维护人员核对并建立浏览器信任的环境。浏览器提示证书不受信任时，先核对证书和访问地址，不以关闭证书校验代替处理。</p><p><code>provided</code> 需要证书、私钥匹配，证书在有效期内，信任链有效，并同时覆盖公共访问地址和服务器内网仓库地址。该分支及不同证书环境需由交付人员单独确认适用性。</p><h2 id="入口形式" tabindex="-1">入口形式 <a class="header-anchor" href="#入口形式" aria-label="Permalink to &quot;入口形式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>地址形式</th><th>默认端口</th></tr></thead><tbody><tr><td>公共入口</td><td><code>https://&lt;公共地址&gt;:&lt;公共端口&gt;/</code></td><td><code>443</code></td></tr><tr><td>管理入口</td><td><code>http://&lt;内网地址&gt;:&lt;管理端口&gt;/admin/</code></td><td><code>18100</code></td></tr></tbody></table><p>尖括号内容是占位说明，不是可直接访问的地址。默认 HTTPS 端口在浏览器中可以省略；仍以安装结果给出的地址为准。</p><h2 id="安装后的材料" tabindex="-1">安装后的材料 <a class="header-anchor" href="#安装后的材料" aria-label="Permalink to &quot;安装后的材料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>材料</th><th>用途</th></tr></thead><tbody><tr><td>完整原安装包</td><td>保留版本与完整性材料，用于经确认的同包重新安装</td></tr><tr><td>安装结果打印的两个入口</td><td>分别交付给平台管理员和组织成员</td></tr><tr><td>安装终端给出的日志路径</td><td>查询安装阶段、错误及原因；默认程序目录下为 <code>logs/install-*.log</code></td></tr><tr><td>程序目录中的 <code>uninstall.sh</code></td><td>通过终端确认卸载范围</td></tr></tbody></table><p>下一步：<a href="/induframe-docs/zh/installation/install.html">填写并完成安装</a> · <a href="/induframe-docs/zh/installation/troubleshooting.html">排查安装问题</a>。</p>',20)])])}const b=d(r,[["render",c]]);export{m as __pageData,b as default};
